insert into public.questions (subject, skill_tag, difficulty, format, purpose, stem_i18n, choices, answer, explanation_i18n, status) values
('math', 'arithmetic-fractions', 1, 'mc', 'placement', '{"en": "What is 3/4 + 1/8?", "ko": "3/4 + 1/8 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "7/8"}}, {"id": "b", "text_i18n": {"en": "4/12"}}, {"id": "c", "text_i18n": {"en": "1/2"}}, {"id": "d", "text_i18n": {"en": "5/8"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Convert 3/4 to 6/8, then 6/8 + 1/8 = 7/8.", "ko": "3/4를 6/8로 통분하면 6/8 + 1/8 = 7/8 입니다."}'::jsonb, 'published'),
('math', 'arithmetic-decimals', 1, 'mc', 'placement', '{"en": "What is 0.6 × 0.3?", "ko": "0.6 × 0.3 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "1.8"}}, {"id": "b", "text_i18n": {"en": "0.18"}}, {"id": "c", "text_i18n": {"en": "0.018"}}, {"id": "d", "text_i18n": {"en": "18"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "6 × 3 = 18, and there are two decimal places total, so 0.18.", "ko": "6 × 3 = 18이고 소수점 아래 자리수가 총 2개이므로 0.18입니다."}'::jsonb, 'published'),
('math', 'arithmetic-negatives', 1, 'mc', 'placement', '{"en": "What is −7 + 12?", "ko": "−7 + 12 는 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "−19"}}, {"id": "b", "text_i18n": {"en": "19"}}, {"id": "c", "text_i18n": {"en": "5"}}, {"id": "d", "text_i18n": {"en": "−5"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "12 − 7 = 5. The larger absolute value (12) is positive.", "ko": "12 − 7 = 5. 절댓값이 큰 12가 양수이므로 답도 양수입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-percent', 2, 'mc', 'placement', '{"en": "What is 15% of 80?", "ko": "80의 15%는 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "12"}}, {"id": "b", "text_i18n": {"en": "15"}}, {"id": "c", "text_i18n": {"en": "8"}}, {"id": "d", "text_i18n": {"en": "20"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "0.15 × 80 = 12.", "ko": "0.15 × 80 = 12 입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-ratio', 2, 'mc', 'placement', '{"en": "A recipe uses 2 cups of flour for every 3 cups of milk. How much flour is needed for 9 cups of milk?", "ko": "우유 3컵마다 밀가루 2컵을 쓰는 레시피가 있습니다. 우유 9컵에는 밀가루 몇 컵이 필요한가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "4 cups"}}, {"id": "b", "text_i18n": {"en": "6 cups"}}, {"id": "c", "text_i18n": {"en": "9 cups"}}, {"id": "d", "text_i18n": {"en": "13.5 cups"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "9 ÷ 3 = 3 groups, 2 × 3 = 6 cups of flour.", "ko": "우유 9컵은 3배이므로 밀가루도 2 × 3 = 6컵입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-exponents', 2, 'mc', 'placement', '{"en": "What is 2³ × 2²?", "ko": "2³ × 2² 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "2⁵ = 32"}}, {"id": "b", "text_i18n": {"en": "2⁶ = 64"}}, {"id": "c", "text_i18n": {"en": "4⁵ = 1024"}}, {"id": "d", "text_i18n": {"en": "2 = 2"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Same base: add exponents. 3 + 2 = 5, so 2⁵ = 32.", "ko": "밑이 같으면 지수를 더합니다. 3 + 2 = 5이므로 2⁵ = 32입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-order-of-operations', 2, 'mc', 'placement', '{"en": "What is 4 + 3 × (6 − 4)²?", "ko": "4 + 3 × (6 − 4)² 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "16"}}, {"id": "b", "text_i18n": {"en": "28"}}, {"id": "c", "text_i18n": {"en": "10"}}, {"id": "d", "text_i18n": {"en": "196"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "(6−4)² = 4, then 3 × 4 = 12, then 4 + 12 = 16.", "ko": "(6−4)² = 4, 3 × 4 = 12, 4 + 12 = 16 순서로 계산합니다."}'::jsonb, 'published'),
('math', 'algebra-one-step-equations', 3, 'mc', 'placement', '{"en": "Solve for x: 3x − 5 = 16", "ko": "x를 구하세요: 3x − 5 = 16"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 3"}}, {"id": "b", "text_i18n": {"en": "x = 7"}}, {"id": "c", "text_i18n": {"en": "x = 11/3"}}, {"id": "d", "text_i18n": {"en": "x = 21"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "3x = 21, so x = 7.", "ko": "3x = 21 이므로 x = 7 입니다."}'::jsonb, 'published'),
('math', 'algebra-linear-graphs', 3, 'mc', 'placement', '{"en": "What is the slope of the line through (1, 2) and (3, 8)?", "ko": "점 (1, 2)와 (3, 8)을 지나는 직선의 기울기는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "6"}}, {"id": "b", "text_i18n": {"en": "1/3"}}, {"id": "c", "text_i18n": {"en": "3"}}, {"id": "d", "text_i18n": {"en": "2"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "slope = (8−2)/(3−1) = 6/2 = 3.", "ko": "기울기 = (8−2)/(3−1) = 6/2 = 3 입니다."}'::jsonb, 'published'),
('math', 'geometry-area', 2, 'mc', 'placement', '{"en": "A rectangle is 8 cm long and 5 cm wide. What is its area?", "ko": "가로 8cm, 세로 5cm 직사각형의 넓이는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "13 cm²"}}, {"id": "b", "text_i18n": {"en": "26 cm²"}}, {"id": "c", "text_i18n": {"en": "40 cm²"}}, {"id": "d", "text_i18n": {"en": "80 cm²"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Area = length × width = 8 × 5 = 40 cm².", "ko": "넓이 = 가로 × 세로 = 8 × 5 = 40 cm² 입니다."}'::jsonb, 'published'),
('math', 'data-mean', 2, 'mc', 'placement', '{"en": "What is the mean of 4, 7, 9, and 12?", "ko": "4, 7, 9, 12의 평균은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "7"}}, {"id": "b", "text_i18n": {"en": "8"}}, {"id": "c", "text_i18n": {"en": "9"}}, {"id": "d", "text_i18n": {"en": "32"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "(4+7+9+12)/4 = 32/4 = 8.", "ko": "(4+7+9+12)/4 = 32/4 = 8 입니다."}'::jsonb, 'published'),
('math', 'algebra-systems', 4, 'mc', 'placement', '{"en": "If x + y = 10 and x − y = 4, what is x?", "ko": "x + y = 10 이고 x − y = 4 일 때, x는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "3"}}, {"id": "b", "text_i18n": {"en": "6"}}, {"id": "c", "text_i18n": {"en": "7"}}, {"id": "d", "text_i18n": {"en": "10"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Add the equations: 2x = 14, so x = 7.", "ko": "두 식을 더하면 2x = 14, x = 7 입니다."}'::jsonb, 'published'),
('rla', 'grammar-nouns', 1, 'mc', 'placement', '{"en": "Choose the correct plural: ''There are three ___ in the yard.''", "ko": "올바른 복수형을 고르세요: ''There are three ___ in the yard.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "child"}}, {"id": "b", "text_i18n": {"en": "childs"}}, {"id": "c", "text_i18n": {"en": "children"}}, {"id": "d", "text_i18n": {"en": "childrens"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "''Child'' has an irregular plural: ''children''.", "ko": "''child''의 복수형은 불규칙형인 ''children''입니다."}'::jsonb, 'published'),
('rla', 'grammar-verb-agreement', 2, 'mc', 'placement', '{"en": "Choose the correct verb: ''Each of the students ___ a laptop.''", "ko": "올바른 동사를 고르세요: ''Each of the students ___ a laptop.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "have"}}, {"id": "b", "text_i18n": {"en": "has"}}, {"id": "c", "text_i18n": {"en": "are having"}}, {"id": "d", "text_i18n": {"en": "were having"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "''Each'' is singular, so use ''has''.", "ko": "''Each''는 단수 취급하므로 ''has''를 씁니다."}'::jsonb, 'published'),
('rla', 'grammar-pronouns', 2, 'mc', 'placement', '{"en": "Choose the correct pronoun: ''My brother and ___ went to the market.''", "ko": "올바른 대명사를 고르세요: ''My brother and ___ went to the market.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "me"}}, {"id": "b", "text_i18n": {"en": "I"}}, {"id": "c", "text_i18n": {"en": "myself"}}, {"id": "d", "text_i18n": {"en": "mine"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Subject position needs the subject pronoun ''I''.", "ko": "주어 자리에는 주격 대명사 ''I''를 씁니다."}'::jsonb, 'published'),
('rla', 'grammar-punctuation', 2, 'mc', 'placement', '{"en": "Which sentence is punctuated correctly?", "ko": "구두점이 올바른 문장을 고르세요."}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Its raining, we stayed inside."}}, {"id": "b", "text_i18n": {"en": "It''s raining, so we stayed inside."}}, {"id": "c", "text_i18n": {"en": "Its'' raining so we stayed inside."}}, {"id": "d", "text_i18n": {"en": "It''s raining so, we stayed inside."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "''It''s'' = ''it is''; a comma goes before the conjunction ''so'' joining two clauses.", "ko": "''It''s''는 ''it is''의 축약형이고, 두 절을 잇는 접속사 ''so'' 앞에 쉼표를 씁니다."}'::jsonb, 'published'),
('rla', 'grammar-sentence-structure', 3, 'mc', 'placement', '{"en": "Which of the following is a complete sentence?", "ko": "완전한 문장을 고르세요."}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Because the rain stopped."}}, {"id": "b", "text_i18n": {"en": "Running through the park."}}, {"id": "c", "text_i18n": {"en": "The library opens at nine."}}, {"id": "d", "text_i18n": {"en": "After we finished dinner and washed the dishes."}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "It has a subject (the library) and a main verb (opens); the others are fragments.", "ko": "주어(the library)와 본동사(opens)가 있는 완전한 문장입니다. 나머지는 조각문입니다."}'::jsonb, 'published'),
('rla', 'reading-main-idea', 3, 'mc', 'placement', '{"en": "\"Bees are vital to farming. As they collect nectar, they carry pollen between flowers, which lets crops produce fruit. Without bees, many foods we eat every day would disappear.\" — What is the main idea?", "ko": "\"Bees are vital to farming...\" 지문의 중심 생각은 무엇인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Bees make honey that people enjoy."}}, {"id": "b", "text_i18n": {"en": "Bees are essential for growing the food we eat."}}, {"id": "c", "text_i18n": {"en": "Flowers need water to produce fruit."}}, {"id": "d", "text_i18n": {"en": "Farming is difficult without machines."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "The passage focuses on bees'' role in food production through pollination.", "ko": "지문은 수분(pollination)을 통해 벌이 식량 생산에 필수적이라는 내용입니다."}'::jsonb, 'published'),
('rla', 'reading-inference', 3, 'mc', 'placement', '{"en": "\"Maria checked her watch again and tapped her foot as the bus finally appeared around the corner.\" — What can you infer about Maria?", "ko": "\"Maria checked her watch again...\" 에서 Maria에 대해 추론할 수 있는 것은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "She is waiting impatiently."}}, {"id": "b", "text_i18n": {"en": "She missed the bus."}}, {"id": "c", "text_i18n": {"en": "She dislikes buses."}}, {"id": "d", "text_i18n": {"en": "Her watch is broken."}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Checking the watch repeatedly and tapping her foot are signs of impatience.", "ko": "시계를 반복해서 보고 발을 구르는 행동은 초조함의 표시입니다."}'::jsonb, 'published'),
('rla', 'reading-detail', 2, 'mc', 'placement', '{"en": "\"The market opens at 6 a.m. on weekdays but at 8 a.m. on weekends.\" — When does the market open on Saturday?", "ko": "\"The market opens at 6 a.m. on weekdays but at 8 a.m. on weekends.\" — 토요일에는 몇 시에 여나요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "6 a.m."}}, {"id": "b", "text_i18n": {"en": "7 a.m."}}, {"id": "c", "text_i18n": {"en": "8 a.m."}}, {"id": "d", "text_i18n": {"en": "It is closed."}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Saturday is a weekend, so it opens at 8 a.m.", "ko": "토요일은 주말이므로 오전 8시에 엽니다."}'::jsonb, 'published'),
('rla', 'grammar-modifiers', 3, 'mc', 'placement', '{"en": "Choose the correct word: ''She sings very ___.''", "ko": "올바른 단어를 고르세요: ''She sings very ___.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "good"}}, {"id": "b", "text_i18n": {"en": "well"}}, {"id": "c", "text_i18n": {"en": "goodly"}}, {"id": "d", "text_i18n": {"en": "best"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "An adverb (''well'') modifies the verb ''sings''.", "ko": "동사 ''sings''를 꾸미는 것은 부사 ''well''입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-arith-prop', 1, 'mc', 'practice', '{"en": "Which number is a factor of 24?", "ko": "24의 약수인 것은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "5"}}, {"id": "b", "text_i18n": {"en": "7"}}, {"id": "c", "text_i18n": {"en": "8"}}, {"id": "d", "text_i18n": {"en": "9"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "24 ÷ 8 = 3 with no remainder, so 8 is a factor.", "ko": "24 ÷ 8 = 3으로 나누어떨어지므로 8은 24의 약수입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-arith-prop', 2, 'mc', 'practice', '{"en": "What is the prime factorization of 36?", "ko": "36을 소인수분해하면?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "2 × 18"}}, {"id": "b", "text_i18n": {"en": "2² × 3²"}}, {"id": "c", "text_i18n": {"en": "4 × 9"}}, {"id": "d", "text_i18n": {"en": "6²"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "36 = 4 × 9 = 2² × 3². Only primes appear in a prime factorization.", "ko": "36 = 4 × 9 = 2² × 3². 소인수분해에는 소수만 나타나야 합니다."}'::jsonb, 'published'),
('rla', 'grammar-nouns', 1, 'mc', 'practice', '{"en": "Which word in this sentence is a noun? ''The teacher quickly closed the door.''", "ko": "다음 문장에서 명사인 것은? ''The teacher quickly closed the door.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "quickly"}}, {"id": "b", "text_i18n": {"en": "closed"}}, {"id": "c", "text_i18n": {"en": "teacher"}}, {"id": "d", "text_i18n": {"en": "the"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "''Teacher'' names a person, so it is a noun (''door'' is also a noun).", "ko": "''teacher''는 사람을 가리키는 명사입니다 (''door''도 명사)."}'::jsonb, 'published'),
('rla', 'grammar-nouns', 2, 'mc', 'practice', '{"en": "Choose the correct possessive: ''The ___ toys are everywhere.''", "ko": "올바른 소유격을 고르세요: ''The ___ toys are everywhere.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "childrens"}}, {"id": "b", "text_i18n": {"en": "children''s"}}, {"id": "c", "text_i18n": {"en": "childrens''"}}, {"id": "d", "text_i18n": {"en": "children"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "''Children'' is already plural; add apostrophe + s: children''s.", "ko": "''children''은 이미 복수형이므로 아포스트로피 + s를 붙여 children''s가 됩니다."}'::jsonb, 'published'),
('math', 'factors-multiples', 1, 'mc', 'practice', '{"en": "What is the greatest common factor (GCF) of 18 and 24?", "ko": "18과 24의 최대공약수는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "2"}}, {"id": "b", "text_i18n": {"en": "3"}}, {"id": "c", "text_i18n": {"en": "6"}}, {"id": "d", "text_i18n": {"en": "12"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Factors of 18: 1,2,3,6,9,18. Factors of 24: 1,2,3,4,6,8,12,24. The greatest shared factor is 6.", "ko": "18의 약수는 1,2,3,6,9,18이고 24의 약수는 1,2,3,4,6,8,12,24입니다. 공통 약수 중 가장 큰 수는 6입니다."}'::jsonb, 'published'),
('math', 'factors-multiples', 1, 'mc', 'practice', '{"en": "What is the least common multiple (LCM) of 4 and 6?", "ko": "4와 6의 최소공배수는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "2"}}, {"id": "b", "text_i18n": {"en": "10"}}, {"id": "c", "text_i18n": {"en": "12"}}, {"id": "d", "text_i18n": {"en": "24"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Multiples of 4: 4,8,12… Multiples of 6: 6,12… The smallest shared multiple is 12.", "ko": "4의 배수는 4,8,12…, 6의 배수는 6,12…입니다. 처음으로 겹치는 배수는 12입니다."}'::jsonb, 'published'),
('math', 'factors-multiples', 2, 'mc', 'practice', '{"en": "Which of the following is a prime number?", "ko": "다음 중 소수(prime)는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "51"}}, {"id": "b", "text_i18n": {"en": "57"}}, {"id": "c", "text_i18n": {"en": "61"}}, {"id": "d", "text_i18n": {"en": "63"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "51 = 3×17, 57 = 3×19, 63 = 7×9. Only 61 has no factors other than 1 and itself.", "ko": "51 = 3×17, 57 = 3×19, 63 = 7×9로 합성수입니다. 61만 1과 자기 자신 외의 약수가 없습니다."}'::jsonb, 'published'),
('math', 'factors-multiples', 2, 'mc', 'practice', '{"en": "What is the prime factorization of 84?", "ko": "84를 소인수분해하면?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "2 × 42"}}, {"id": "b", "text_i18n": {"en": "4 × 21"}}, {"id": "c", "text_i18n": {"en": "2² × 3 × 7"}}, {"id": "d", "text_i18n": {"en": "2 × 3 × 14"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "84 = 2×42 = 2×2×21 = 2²×3×7. All factors must be prime.", "ko": "84 = 2×42 = 2×2×21 = 2²×3×7. 소인수분해는 모든 인수가 소수여야 합니다."}'::jsonb, 'published'),
('math', 'factors-multiples', 1, 'mc', 'practice', '{"en": "Which number is a multiple of 7?", "ko": "다음 중 7의 배수는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "27"}}, {"id": "b", "text_i18n": {"en": "42"}}, {"id": "c", "text_i18n": {"en": "57"}}, {"id": "d", "text_i18n": {"en": "75"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "42 = 7 × 6. The others are not divisible by 7.", "ko": "42 = 7 × 6입니다. 나머지는 7로 나누어떨어지지 않습니다."}'::jsonb, 'published'),
('math', 'ratios-rates', 1, 'mc', 'practice', '{"en": "A bus travels 240 km in 3 hours. What is its average speed?", "ko": "버스가 3시간에 240km를 갔습니다. 평균 속력은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "60 km/h"}}, {"id": "b", "text_i18n": {"en": "70 km/h"}}, {"id": "c", "text_i18n": {"en": "80 km/h"}}, {"id": "d", "text_i18n": {"en": "90 km/h"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Speed = distance ÷ time = 240 ÷ 3 = 80 km/h.", "ko": "속력 = 거리 ÷ 시간 = 240 ÷ 3 = 80 km/h."}'::jsonb, 'published'),
('math', 'ratios-rates', 2, 'mc', 'practice', '{"en": "Two numbers are in the ratio 3:5 and their sum is 40. What is the smaller number?", "ko": "두 수의 비가 3:5이고 합이 40일 때, 작은 수는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "8"}}, {"id": "b", "text_i18n": {"en": "15"}}, {"id": "c", "text_i18n": {"en": "24"}}, {"id": "d", "text_i18n": {"en": "25"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "3+5 = 8 parts. Each part = 40÷8 = 5. Smaller number = 3×5 = 15.", "ko": "3+5 = 8등분입니다. 한 부분은 40÷8 = 5이므로 작은 수는 3×5 = 15입니다."}'::jsonb, 'published'),
('math', 'ratios-rates', 1, 'mc', 'practice', '{"en": "A dozen eggs costs $3.60. What is the cost per egg?", "ko": "달걀 12개가 3.60달러입니다. 달걀 1개의 가격은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "$0.25"}}, {"id": "b", "text_i18n": {"en": "$0.30"}}, {"id": "c", "text_i18n": {"en": "$0.36"}}, {"id": "d", "text_i18n": {"en": "$0.40"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "$3.60 ÷ 12 = $0.30 per egg.", "ko": "3.60 ÷ 12 = 개당 0.30달러입니다."}'::jsonb, 'published'),
('math', 'ratios-rates', 2, 'mc', 'practice', '{"en": "On a map, 1 cm represents 50 km. How far apart are two cities that are 7 cm apart on the map?", "ko": "지도에서 1cm는 실제 50km입니다. 지도상 7cm 떨어진 두 도시의 실제 거리는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "57 km"}}, {"id": "b", "text_i18n": {"en": "300 km"}}, {"id": "c", "text_i18n": {"en": "350 km"}}, {"id": "d", "text_i18n": {"en": "700 km"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "7 × 50 = 350 km.", "ko": "7 × 50 = 350km입니다."}'::jsonb, 'published'),
('math', 'ratios-rates', 2, 'mc', 'practice', '{"en": "A recipe uses 2/3 cup of sugar for 12 cookies. How much sugar is needed for 36 cookies?", "ko": "쿠키 12개에 설탕 2/3컵을 씁니다. 쿠키 36개에는 설탕이 얼마나 필요한가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "1 cup"}}, {"id": "b", "text_i18n": {"en": "1 1/3 cups"}}, {"id": "c", "text_i18n": {"en": "2 cups"}}, {"id": "d", "text_i18n": {"en": "3 cups"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "36 is 3 times 12, so sugar = 3 × 2/3 = 2 cups.", "ko": "36개는 12개의 3배이므로 설탕도 2/3 × 3 = 2컵입니다."}'::jsonb, 'published'),
('math', 'percentages', 1, 'mc', 'practice', '{"en": "What is 25% of 84?", "ko": "84의 25%는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "16"}}, {"id": "b", "text_i18n": {"en": "21"}}, {"id": "c", "text_i18n": {"en": "25"}}, {"id": "d", "text_i18n": {"en": "42"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "25% = 1/4, and 84 ÷ 4 = 21.", "ko": "25%는 1/4이므로 84 ÷ 4 = 21입니다."}'::jsonb, 'published'),
('math', 'percentages', 2, 'mc', 'practice', '{"en": "45 is what percent of 180?", "ko": "45는 180의 몇 %인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "20%"}}, {"id": "b", "text_i18n": {"en": "25%"}}, {"id": "c", "text_i18n": {"en": "30%"}}, {"id": "d", "text_i18n": {"en": "40%"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "45 ÷ 180 = 0.25 = 25%.", "ko": "45 ÷ 180 = 0.25 = 25%입니다."}'::jsonb, 'published'),
('math', 'percentages', 2, 'mc', 'practice', '{"en": "A jacket costs $60. It is on sale for 20% off. What is the sale price?", "ko": "60달러짜리 재킷을 20% 할인합니다. 할인가는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "$40"}}, {"id": "b", "text_i18n": {"en": "$45"}}, {"id": "c", "text_i18n": {"en": "$48"}}, {"id": "d", "text_i18n": {"en": "$52"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Discount = 60 × 0.20 = $12. Sale price = 60 − 12 = $48.", "ko": "할인액 = 60 × 0.20 = 12달러. 할인가 = 60 − 12 = 48달러입니다."}'::jsonb, 'published'),
('math', 'percentages', 3, 'mc', 'practice', '{"en": "A population of 30,000 increases by 15%. What is the new population?", "ko": "인구 30,000명이 15% 증가했습니다. 새 인구는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "30,450"}}, {"id": "b", "text_i18n": {"en": "33,000"}}, {"id": "c", "text_i18n": {"en": "34,500"}}, {"id": "d", "text_i18n": {"en": "45,000"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Increase = 30,000 × 0.15 = 4,500. New total = 34,500.", "ko": "증가분 = 30,000 × 0.15 = 4,500명. 새 인구 = 34,500명입니다."}'::jsonb, 'published'),
('math', 'percentages', 2, 'mc', 'practice', '{"en": "Sales tax is 7%. What is the total cost of a $50 item including tax?", "ko": "판매세가 7%일 때, 50달러 물건의 세금 포함 총액은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "$53.50"}}, {"id": "b", "text_i18n": {"en": "$57.00"}}, {"id": "c", "text_i18n": {"en": "$50.70"}}, {"id": "d", "text_i18n": {"en": "$35.00"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Tax = 50 × 0.07 = $3.50. Total = $53.50.", "ko": "세금 = 50 × 0.07 = 3.50달러. 총액 = 53.50달러입니다."}'::jsonb, 'published'),
('math', 'percentages', 3, 'mc', 'practice', '{"en": "What is 120% of 45?", "ko": "45의 120%는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "36"}}, {"id": "b", "text_i18n": {"en": "54"}}, {"id": "c", "text_i18n": {"en": "56"}}, {"id": "d", "text_i18n": {"en": "65"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "120% = 1.2, and 45 × 1.2 = 54.", "ko": "120% = 1.2이므로 45 × 1.2 = 54입니다."}'::jsonb, 'published'),
('math', 'exponents-order-of-operations', 2, 'mc', 'practice', '{"en": "What is 5 + 2 × 3²?", "ko": "5 + 2 × 3² 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "23"}}, {"id": "b", "text_i18n": {"en": "63"}}, {"id": "c", "text_i18n": {"en": "41"}}, {"id": "d", "text_i18n": {"en": "21"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Exponent first: 3² = 9. Then 2×9 = 18. Then 5+18 = 23.", "ko": "지수 먼저: 3² = 9. 다음 2×9 = 18, 마지막 5+18 = 23입니다."}'::jsonb, 'published'),
('math', 'exponents-order-of-operations', 1, 'mc', 'practice', '{"en": "What is (−3)²?", "ko": "(−3)² 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "−9"}}, {"id": "b", "text_i18n": {"en": "−6"}}, {"id": "c", "text_i18n": {"en": "6"}}, {"id": "d", "text_i18n": {"en": "9"}}]'::jsonb, '{"choice": "d"}'::jsonb, '{"en": "(−3)² = (−3)×(−3) = 9. A negative times a negative is positive.", "ko": "(−3)² = (−3)×(−3) = 9. 음수 × 음수 = 양수입니다."}'::jsonb, 'published'),
('math', 'exponents-order-of-operations', 1, 'mc', 'practice', '{"en": "What is 2⁴?", "ko": "2⁴ 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "8"}}, {"id": "b", "text_i18n": {"en": "16"}}, {"id": "c", "text_i18n": {"en": "24"}}, {"id": "d", "text_i18n": {"en": "32"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "2×2×2×2 = 16.", "ko": "2×2×2×2 = 16입니다."}'::jsonb, 'published'),
('math', 'exponents-order-of-operations', 3, 'mc', 'practice', '{"en": "What is 18 ÷ (7 − 4) + 2 × 5?", "ko": "18 ÷ (7 − 4) + 2 × 5 는 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "16"}}, {"id": "b", "text_i18n": {"en": "40"}}, {"id": "c", "text_i18n": {"en": "26"}}, {"id": "d", "text_i18n": {"en": "11"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Parentheses: 7−4 = 3. Then 18÷3 = 6 and 2×5 = 10. Finally 6+10 = 16.", "ko": "괄호 먼저: 7−4 = 3. 그다음 18÷3 = 6, 2×5 = 10. 마지막으로 6+10 = 16입니다."}'::jsonb, 'published'),
('math', 'exponents-order-of-operations', 2, 'mc', 'practice', '{"en": "What is 3³ − 2⁴?", "ko": "3³ − 2⁴ 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "1"}}, {"id": "b", "text_i18n": {"en": "11"}}, {"id": "c", "text_i18n": {"en": "19"}}, {"id": "d", "text_i18n": {"en": "−7"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "3³ = 27 and 2⁴ = 16, so 27 − 16 = 11.", "ko": "3³ = 27, 2⁴ = 16이므로 27 − 16 = 11입니다."}'::jsonb, 'published'),
('math', 'variables-expressions', 1, 'mc', 'practice', '{"en": "Evaluate 3x − 7 when x = 5.", "ko": "x = 5일 때 3x − 7의 값은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "8"}}, {"id": "b", "text_i18n": {"en": "15"}}, {"id": "c", "text_i18n": {"en": "22"}}, {"id": "d", "text_i18n": {"en": "1"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "3(5) − 7 = 15 − 7 = 8.", "ko": "3×5 − 7 = 15 − 7 = 8입니다."}'::jsonb, 'published'),
('math', 'variables-expressions', 2, 'mc', 'practice', '{"en": "Simplify: 4a + 2b − a + 5b", "ko": "간단히 하세요: 4a + 2b − a + 5b"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "3a + 7b"}}, {"id": "b", "text_i18n": {"en": "5a + 7b"}}, {"id": "c", "text_i18n": {"en": "3a + 3b"}}, {"id": "d", "text_i18n": {"en": "10ab"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Combine like terms: (4a − a) + (2b + 5b) = 3a + 7b.", "ko": "동류항끼리 계산: (4a − a) + (2b + 5b) = 3a + 7b입니다."}'::jsonb, 'published'),
('math', 'variables-expressions', 2, 'mc', 'practice', '{"en": "Which expression means \"5 less than twice a number n\"?", "ko": "\"어떤 수 n의 2배보다 5 작은 수\"를 식으로 나타내면?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "5 − 2n"}}, {"id": "b", "text_i18n": {"en": "2n − 5"}}, {"id": "c", "text_i18n": {"en": "2(n − 5)"}}, {"id": "d", "text_i18n": {"en": "5n − 2"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "\"Twice a number\" is 2n; \"5 less than\" that means subtract 5: 2n − 5.", "ko": "\"2배\"는 2n이고, \"그보다 5 작은\"은 5를 빼는 것이므로 2n − 5입니다."}'::jsonb, 'published'),
('math', 'variables-expressions', 3, 'mc', 'practice', '{"en": "Evaluate 2(x + 3)² when x = 1.", "ko": "x = 1일 때 2(x + 3)² 의 값은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "16"}}, {"id": "b", "text_i18n": {"en": "20"}}, {"id": "c", "text_i18n": {"en": "32"}}, {"id": "d", "text_i18n": {"en": "64"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "x+3 = 4, then 4² = 16, then 2×16 = 32.", "ko": "x+3 = 4, 4² = 16, 2×16 = 32입니다."}'::jsonb, 'published'),
('math', 'variables-expressions', 3, 'mc', 'practice', '{"en": "Simplify: 7x − (2x − 4)", "ko": "간단히 하세요: 7x − (2x − 4)"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "5x − 4"}}, {"id": "b", "text_i18n": {"en": "5x + 4"}}, {"id": "c", "text_i18n": {"en": "9x − 4"}}, {"id": "d", "text_i18n": {"en": "5x"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Distribute the minus: 7x − 2x + 4 = 5x + 4.", "ko": "괄호 앞 음수를 분배하면 7x − 2x + 4 = 5x + 4입니다."}'::jsonb, 'published'),
('math', 'equations-inequalities-intro', 1, 'mc', 'practice', '{"en": "Solve: x + 9 = 4", "ko": "x를 구하세요: x + 9 = 4"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 13"}}, {"id": "b", "text_i18n": {"en": "x = 5"}}, {"id": "c", "text_i18n": {"en": "x = −5"}}, {"id": "d", "text_i18n": {"en": "x = −13"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Subtract 9 from both sides: x = 4 − 9 = −5.", "ko": "양변에서 9를 빼면 x = 4 − 9 = −5입니다."}'::jsonb, 'published'),
('math', 'equations-inequalities-intro', 1, 'mc', 'practice', '{"en": "Solve: x ÷ 4 = 7", "ko": "x를 구하세요: x ÷ 4 = 7"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 3"}}, {"id": "b", "text_i18n": {"en": "x = 11"}}, {"id": "c", "text_i18n": {"en": "x = 28"}}, {"id": "d", "text_i18n": {"en": "x = 1.75"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Multiply both sides by 4: x = 7 × 4 = 28.", "ko": "양변에 4를 곱하면 x = 7 × 4 = 28입니다."}'::jsonb, 'published'),
('math', 'equations-inequalities-intro', 2, 'mc', 'practice', '{"en": "Which value of x satisfies 2x + 1 > 7?", "ko": "2x + 1 > 7 을 만족하는 x 값은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "1"}}, {"id": "b", "text_i18n": {"en": "2"}}, {"id": "c", "text_i18n": {"en": "3"}}, {"id": "d", "text_i18n": {"en": "4"}}]'::jsonb, '{"choice": "d"}'::jsonb, '{"en": "2x > 6, so x > 3. Only 4 is greater than 3.", "ko": "2x > 6이므로 x > 3. 보기 중 3보다 큰 값은 4뿐입니다."}'::jsonb, 'published'),
('math', 'equations-inequalities-intro', 1, 'mc', 'practice', '{"en": "Solve: 5x = 45", "ko": "x를 구하세요: 5x = 45"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 5"}}, {"id": "b", "text_i18n": {"en": "x = 8"}}, {"id": "c", "text_i18n": {"en": "x = 9"}}, {"id": "d", "text_i18n": {"en": "x = 40"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Divide both sides by 5: x = 45 ÷ 5 = 9.", "ko": "양변을 5로 나누면 x = 45 ÷ 5 = 9입니다."}'::jsonb, 'published'),
('math', 'equations-inequalities-intro', 2, 'mc', 'practice', '{"en": "The inequality x ≥ 3 describes which set of numbers?", "ko": "부등식 x ≥ 3 이 나타내는 수의 범위는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Only the number 3"}}, {"id": "b", "text_i18n": {"en": "All numbers greater than 3, not including 3"}}, {"id": "c", "text_i18n": {"en": "3 and all numbers greater than 3"}}, {"id": "d", "text_i18n": {"en": "All numbers less than 3"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "The symbol ≥ means \"greater than or equal to\", so 3 is included.", "ko": "≥ 는 \"크거나 같다\"이므로 3도 포함됩니다."}'::jsonb, 'published'),
('math', 'percent-rational-word-problems', 2, 'mc', 'practice', '{"en": "A phone costs $250. With a 12% discount, what do you pay?", "ko": "250달러짜리 휴대폰을 12% 할인받으면 얼마를 내나요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "$220"}}, {"id": "b", "text_i18n": {"en": "$228"}}, {"id": "c", "text_i18n": {"en": "$238"}}, {"id": "d", "text_i18n": {"en": "$280"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Discount = 250 × 0.12 = $30. Price = 250 − 30 = $220.", "ko": "할인액 = 250 × 0.12 = 30달러. 가격 = 250 − 30 = 220달러입니다."}'::jsonb, 'published'),
('math', 'percent-rational-word-problems', 1, 'mc', 'practice', '{"en": "The temperature was −4°C and rose by 9°C. What is the new temperature?", "ko": "기온이 −4°C에서 9°C 올랐습니다. 지금 기온은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "−13°C"}}, {"id": "b", "text_i18n": {"en": "−5°C"}}, {"id": "c", "text_i18n": {"en": "5°C"}}, {"id": "d", "text_i18n": {"en": "13°C"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "−4 + 9 = 5.", "ko": "−4 + 9 = 5입니다."}'::jsonb, 'published'),
('math', 'percent-rational-word-problems', 2, 'mc', 'practice', '{"en": "3/4 of the students in a class is 24 students. How many students are in the class?", "ko": "학급 학생의 3/4이 24명입니다. 전체 학생 수는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "18"}}, {"id": "b", "text_i18n": {"en": "28"}}, {"id": "c", "text_i18n": {"en": "30"}}, {"id": "d", "text_i18n": {"en": "32"}}]'::jsonb, '{"choice": "d"}'::jsonb, '{"en": "If 3/4 of the class = 24, then 1/4 = 8, so the whole class = 32.", "ko": "3/4이 24명이면 1/4은 8명이므로 전체는 32명입니다."}'::jsonb, 'published'),
('math', 'percent-rational-word-problems', 2, 'mc', 'practice', '{"en": "Nina owes her friend $35. She pays back $20. Which number represents what she still owes?", "ko": "니나가 친구에게 35달러를 빚졌고 20달러를 갚았습니다. 남은 빚을 수로 나타내면?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "−55"}}, {"id": "b", "text_i18n": {"en": "−15"}}, {"id": "c", "text_i18n": {"en": "15"}}, {"id": "d", "text_i18n": {"en": "55"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Debt is negative: −35 + 20 = −15.", "ko": "빚은 음수로 나타냅니다: −35 + 20 = −15입니다."}'::jsonb, 'published'),
('math', 'proportional-relationships', 2, 'mc', 'practice', '{"en": "y is proportional to x. When x = 4, y = 12. What is y when x = 7?", "ko": "y는 x에 정비례합니다. x = 4일 때 y = 12라면, x = 7일 때 y는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "15"}}, {"id": "b", "text_i18n": {"en": "19"}}, {"id": "c", "text_i18n": {"en": "21"}}, {"id": "d", "text_i18n": {"en": "28"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "y = 3x (since 12 ÷ 4 = 3). So y = 3 × 7 = 21.", "ko": "비례상수는 12 ÷ 4 = 3이므로 y = 3x. 따라서 y = 3 × 7 = 21입니다."}'::jsonb, 'published'),
('math', 'proportional-relationships', 1, 'mc', 'practice', '{"en": "If 8 pencils cost $2, how much do 20 pencils cost?", "ko": "연필 8자루가 2달러라면 20자루는 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "$4"}}, {"id": "b", "text_i18n": {"en": "$5"}}, {"id": "c", "text_i18n": {"en": "$6"}}, {"id": "d", "text_i18n": {"en": "$10"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "One pencil costs 2 ÷ 8 = $0.25, so 20 × 0.25 = $5.", "ko": "연필 1자루는 2 ÷ 8 = 0.25달러이므로 20 × 0.25 = 5달러입니다."}'::jsonb, 'published'),
('math', 'proportional-relationships', 2, 'mc', 'practice', '{"en": "In the equation y = 3.5x, what is the constant of proportionality?", "ko": "식 y = 3.5x 에서 비례상수는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "y"}}, {"id": "b", "text_i18n": {"en": "x"}}, {"id": "c", "text_i18n": {"en": "3.5"}}, {"id": "d", "text_i18n": {"en": "0.35"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "In y = kx, the constant of proportionality is k = 3.5.", "ko": "y = kx 꼴에서 비례상수는 k = 3.5입니다."}'::jsonb, 'published'),
('math', 'one-two-step-equations', 2, 'mc', 'practice', '{"en": "Solve: 2x − 3 = 11", "ko": "x를 구하세요: 2x − 3 = 11"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 4"}}, {"id": "b", "text_i18n": {"en": "x = 7"}}, {"id": "c", "text_i18n": {"en": "x = 8"}}, {"id": "d", "text_i18n": {"en": "x = 14"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "2x = 14, so x = 7.", "ko": "2x = 14이므로 x = 7입니다."}'::jsonb, 'published'),
('math', 'one-two-step-equations', 2, 'mc', 'practice', '{"en": "Solve: (x + 5) ÷ 3 = 4", "ko": "x를 구하세요: (x + 5) ÷ 3 = 4"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 7"}}, {"id": "b", "text_i18n": {"en": "x = 9"}}, {"id": "c", "text_i18n": {"en": "x = 12"}}, {"id": "d", "text_i18n": {"en": "x = 17"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "x + 5 = 12, so x = 7.", "ko": "x + 5 = 12이므로 x = 7입니다."}'::jsonb, 'published'),
('math', 'one-two-step-equations', 2, 'mc', 'practice', '{"en": "Solve: −4x = 28", "ko": "x를 구하세요: −4x = 28"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 7"}}, {"id": "b", "text_i18n": {"en": "x = −7"}}, {"id": "c", "text_i18n": {"en": "x = 24"}}, {"id": "d", "text_i18n": {"en": "x = −24"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Divide by −4: x = 28 ÷ (−4) = −7.", "ko": "양변을 −4로 나누면 x = −7입니다."}'::jsonb, 'published'),
('math', 'one-two-step-equations', 2, 'mc', 'practice', '{"en": "Solve: 3x + 8 = 2", "ko": "x를 구하세요: 3x + 8 = 2"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 2"}}, {"id": "b", "text_i18n": {"en": "x = −2"}}, {"id": "c", "text_i18n": {"en": "x = 10/3"}}, {"id": "d", "text_i18n": {"en": "x = −10/3"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "3x = −6, so x = −2.", "ko": "3x = 2 − 8 = −6이므로 x = −2입니다."}'::jsonb, 'published'),
('math', 'one-two-step-equations', 2, 'mc', 'practice', '{"en": "Solve: x/2 − 6 = −1", "ko": "x를 구하세요: x/2 − 6 = −1"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = −14"}}, {"id": "b", "text_i18n": {"en": "x = −10"}}, {"id": "c", "text_i18n": {"en": "x = 5"}}, {"id": "d", "text_i18n": {"en": "x = 10"}}]'::jsonb, '{"choice": "d"}'::jsonb, '{"en": "x/2 = 5, so x = 10.", "ko": "x/2 = −1 + 6 = 5이므로 x = 10입니다."}'::jsonb, 'published'),
('math', 'roots-scientific-notation', 1, 'mc', 'practice', '{"en": "What is √81?", "ko": "√81 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "8"}}, {"id": "b", "text_i18n": {"en": "9"}}, {"id": "c", "text_i18n": {"en": "27"}}, {"id": "d", "text_i18n": {"en": "40.5"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "9 × 9 = 81, so √81 = 9.", "ko": "9 × 9 = 81이므로 √81 = 9입니다."}'::jsonb, 'published'),
('math', 'roots-scientific-notation', 2, 'mc', 'practice', '{"en": "What is √49 + √16?", "ko": "√49 + √16 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "√65"}}, {"id": "b", "text_i18n": {"en": "9"}}, {"id": "c", "text_i18n": {"en": "11"}}, {"id": "d", "text_i18n": {"en": "13"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "√49 = 7 and √16 = 4, so 7 + 4 = 11.", "ko": "√49 = 7, √16 = 4이므로 7 + 4 = 11입니다."}'::jsonb, 'published'),
('math', 'roots-scientific-notation', 2, 'mc', 'practice', '{"en": "Write 3.2 × 10⁴ in standard form.", "ko": "3.2 × 10⁴ 을 일반 표기로 쓰면?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "320"}}, {"id": "b", "text_i18n": {"en": "3,200"}}, {"id": "c", "text_i18n": {"en": "32,000"}}, {"id": "d", "text_i18n": {"en": "320,000"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Move the decimal 4 places right: 32,000.", "ko": "소수점을 오른쪽으로 4칸 옮기면 32,000입니다."}'::jsonb, 'published'),
('math', 'roots-scientific-notation', 3, 'mc', 'practice', '{"en": "Write 0.00045 in scientific notation.", "ko": "0.00045 를 과학적 표기법으로 쓰면?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "4.5 × 10⁴"}}, {"id": "b", "text_i18n": {"en": "4.5 × 10⁻⁴"}}, {"id": "c", "text_i18n": {"en": "45 × 10⁻⁵"}}, {"id": "d", "text_i18n": {"en": "4.5 × 10⁻³"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Move the decimal 4 places right to get 4.5; small numbers use a negative exponent: 4.5 × 10⁻⁴.", "ko": "소수점을 오른쪽으로 4칸 옮기면 4.5가 되고, 1보다 작은 수이므로 지수는 음수: 4.5 × 10⁻⁴입니다."}'::jsonb, 'published'),
('math', 'roots-scientific-notation', 3, 'mc', 'practice', '{"en": "√50 is between which two whole numbers?", "ko": "√50 은 어느 두 정수 사이에 있나요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "5 and 6"}}, {"id": "b", "text_i18n": {"en": "6 and 7"}}, {"id": "c", "text_i18n": {"en": "7 and 8"}}, {"id": "d", "text_i18n": {"en": "24 and 26"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "7² = 49 and 8² = 64, and 49 < 50 < 64.", "ko": "7² = 49, 8² = 64이고 49 < 50 < 64이므로 7과 8 사이입니다."}'::jsonb, 'published'),
('math', 'multi-step-equations', 3, 'mc', 'practice', '{"en": "Solve: 3(x − 2) = 15", "ko": "x를 구하세요: 3(x − 2) = 15"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 3"}}, {"id": "b", "text_i18n": {"en": "x = 5"}}, {"id": "c", "text_i18n": {"en": "x = 7"}}, {"id": "d", "text_i18n": {"en": "x = 17/3"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "x − 2 = 5, so x = 7.", "ko": "양변을 3으로 나누면 x − 2 = 5, x = 7입니다."}'::jsonb, 'published'),
('math', 'multi-step-equations', 3, 'mc', 'practice', '{"en": "Solve: 4x + 7 = 2x + 19", "ko": "x를 구하세요: 4x + 7 = 2x + 19"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 4"}}, {"id": "b", "text_i18n": {"en": "x = 6"}}, {"id": "c", "text_i18n": {"en": "x = 12"}}, {"id": "d", "text_i18n": {"en": "x = 13"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "2x = 12, so x = 6.", "ko": "2x = 19 − 7 = 12이므로 x = 6입니다."}'::jsonb, 'published'),
('math', 'multi-step-equations', 4, 'mc', 'practice', '{"en": "Solve: 5 − 2(x − 1) = 11", "ko": "x를 구하세요: 5 − 2(x − 1) = 11"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = −2"}}, {"id": "b", "text_i18n": {"en": "x = 2"}}, {"id": "c", "text_i18n": {"en": "x = −4"}}, {"id": "d", "text_i18n": {"en": "x = 4"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "5 − 2x + 2 = 11 → 7 − 2x = 11 → −2x = 4 → x = −2.", "ko": "괄호를 풀면 5 − 2x + 2 = 11 → 7 − 2x = 11 → −2x = 4 → x = −2입니다."}'::jsonb, 'published'),
('math', 'multi-step-equations', 3, 'mc', 'practice', '{"en": "Solve: (2x/3) + 1 = 9", "ko": "x를 구하세요: (2x/3) + 1 = 9"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 6"}}, {"id": "b", "text_i18n": {"en": "x = 12"}}, {"id": "c", "text_i18n": {"en": "x = 15"}}, {"id": "d", "text_i18n": {"en": "x = 24"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "2x/3 = 8 → 2x = 24 → x = 12.", "ko": "2x/3 = 8 → 2x = 24 → x = 12입니다."}'::jsonb, 'published'),
('math', 'two-variable-equations', 2, 'mc', 'practice', '{"en": "If y = 2x + 3, what is y when x = −2?", "ko": "y = 2x + 3 에서 x = −2일 때 y는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "−7"}}, {"id": "b", "text_i18n": {"en": "−1"}}, {"id": "c", "text_i18n": {"en": "1"}}, {"id": "d", "text_i18n": {"en": "7"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "y = 2(−2) + 3 = −4 + 3 = −1.", "ko": "y = 2×(−2) + 3 = −4 + 3 = −1입니다."}'::jsonb, 'published'),
('math', 'two-variable-equations', 2, 'mc', 'practice', '{"en": "Which point lies on the line y = 3x + 1?", "ko": "직선 y = 3x + 1 위에 있는 점은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "(1, 5)"}}, {"id": "b", "text_i18n": {"en": "(2, 7)"}}, {"id": "c", "text_i18n": {"en": "(3, 8)"}}, {"id": "d", "text_i18n": {"en": "(0, 3)"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Check (2, 7): 3(2) + 1 = 7. ✓ The others don''t satisfy the equation.", "ko": "(2, 7) 확인: 3×2 + 1 = 7 ✓. 나머지 점은 식을 만족하지 않습니다."}'::jsonb, 'published'),
('math', 'linear-equations-graphs', 1, 'mc', 'practice', '{"en": "What is the slope of the line y = −4x + 9?", "ko": "직선 y = −4x + 9 의 기울기는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "9"}}, {"id": "b", "text_i18n": {"en": "4"}}, {"id": "c", "text_i18n": {"en": "−4"}}, {"id": "d", "text_i18n": {"en": "−9"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "In y = mx + b, the slope is m = −4.", "ko": "y = mx + b 꼴에서 기울기는 m = −4입니다."}'::jsonb, 'published'),
('math', 'linear-equations-graphs', 1, 'mc', 'practice', '{"en": "What is the y-intercept of the line y = 5x − 2?", "ko": "직선 y = 5x − 2 의 y절편은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "(0, 5)"}}, {"id": "b", "text_i18n": {"en": "(0, −2)"}}, {"id": "c", "text_i18n": {"en": "(5, 0)"}}, {"id": "d", "text_i18n": {"en": "(−2, 0)"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "At x = 0, y = −2, so the line crosses the y-axis at (0, −2).", "ko": "x = 0일 때 y = −2이므로 y축과 (0, −2)에서 만납니다."}'::jsonb, 'published'),
('math', 'functions-linear-models', 2, 'mc', 'practice', '{"en": "If f(x) = x² − 3, what is f(4)?", "ko": "f(x) = x² − 3 일 때 f(4)는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "5"}}, {"id": "b", "text_i18n": {"en": "13"}}, {"id": "c", "text_i18n": {"en": "19"}}, {"id": "d", "text_i18n": {"en": "1"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "f(4) = 4² − 3 = 16 − 3 = 13.", "ko": "f(4) = 4² − 3 = 16 − 3 = 13입니다."}'::jsonb, 'published'),
('math', 'functions-linear-models', 3, 'mc', 'practice', '{"en": "A table shows x: 1, 2, 3 and y: 5, 8, 11. Which rule fits?", "ko": "표에서 x가 1, 2, 3일 때 y는 5, 8, 11입니다. 규칙은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "y = x + 4"}}, {"id": "b", "text_i18n": {"en": "y = 5x"}}, {"id": "c", "text_i18n": {"en": "y = 3x + 2"}}, {"id": "d", "text_i18n": {"en": "y = 2x + 3"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "y increases by 3 each step (slope 3). Check: 3(1)+2 = 5 ✓, 3(2)+2 = 8 ✓.", "ko": "x가 1 커질 때 y가 3씩 커지므로 기울기 3. 확인: 3×1+2 = 5 ✓, 3×2+2 = 8 ✓."}'::jsonb, 'published'),
('math', 'functions-linear-models', 3, 'mc', 'practice', '{"en": "A taxi charges $3 plus $2 per km. Which function gives the cost C for k km?", "ko": "택시 기본요금 3달러에 km당 2달러입니다. k km 요금 C를 나타내는 식은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "C = 5k"}}, {"id": "b", "text_i18n": {"en": "C = 2k + 3"}}, {"id": "c", "text_i18n": {"en": "C = 3k + 2"}}, {"id": "d", "text_i18n": {"en": "C = 2k − 3"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Fixed $3 plus $2 for each km: C = 2k + 3.", "ko": "고정 3달러 + km당 2달러이므로 C = 2k + 3입니다."}'::jsonb, 'published'),
('math', 'systems-of-equations', 3, 'mc', 'practice', '{"en": "If x + y = 12 and x − y = 2, what is y?", "ko": "x + y = 12, x − y = 2 일 때 y는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "4"}}, {"id": "b", "text_i18n": {"en": "5"}}, {"id": "c", "text_i18n": {"en": "6"}}, {"id": "d", "text_i18n": {"en": "7"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Adding gives 2x = 14, x = 7. Then y = 12 − 7 = 5.", "ko": "두 식을 더하면 2x = 14, x = 7. 따라서 y = 12 − 7 = 5입니다."}'::jsonb, 'published'),
('math', 'systems-of-equations', 3, 'mc', 'practice', '{"en": "Where do the lines y = x + 1 and y = 2x − 3 intersect?", "ko": "직선 y = x + 1 과 y = 2x − 3 의 교점은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "(2, 3)"}}, {"id": "b", "text_i18n": {"en": "(4, 5)"}}, {"id": "c", "text_i18n": {"en": "(−4, −3)"}}, {"id": "d", "text_i18n": {"en": "(1, 2)"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Set x + 1 = 2x − 3 → x = 4, then y = 5.", "ko": "x + 1 = 2x − 3 → x = 4, y = 4 + 1 = 5. 교점은 (4, 5)입니다."}'::jsonb, 'published'),
('math', 'systems-of-equations', 3, 'mc', 'practice', '{"en": "If y = 3x and x + y = 16, what is x?", "ko": "y = 3x 이고 x + y = 16 일 때 x는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "3"}}, {"id": "b", "text_i18n": {"en": "4"}}, {"id": "c", "text_i18n": {"en": "12"}}, {"id": "d", "text_i18n": {"en": "16/3"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Substitute: x + 3x = 16 → 4x = 16 → x = 4.", "ko": "대입하면 x + 3x = 16 → 4x = 16 → x = 4입니다."}'::jsonb, 'published'),
('math', 'geometry-area-perimeter', 1, 'mc', 'practice', '{"en": "What is the perimeter of a rectangle 7 m long and 4 m wide?", "ko": "가로 7m, 세로 4m 직사각형의 둘레는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "11 m"}}, {"id": "b", "text_i18n": {"en": "22 m"}}, {"id": "c", "text_i18n": {"en": "28 m"}}, {"id": "d", "text_i18n": {"en": "14 m"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Perimeter = 2(7 + 4) = 22 m.", "ko": "둘레 = 2 × (7 + 4) = 22m입니다."}'::jsonb, 'published'),
('math', 'geometry-area-perimeter', 1, 'mc', 'practice', '{"en": "What is the area of a triangle with base 10 cm and height 6 cm?", "ko": "밑변 10cm, 높이 6cm인 삼각형의 넓이는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "16 cm²"}}, {"id": "b", "text_i18n": {"en": "30 cm²"}}, {"id": "c", "text_i18n": {"en": "60 cm²"}}, {"id": "d", "text_i18n": {"en": "120 cm²"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Area = (base × height) ÷ 2 = (10 × 6) ÷ 2 = 30 cm².", "ko": "넓이 = 밑변 × 높이 ÷ 2 = 10 × 6 ÷ 2 = 30cm²입니다."}'::jsonb, 'published'),
('math', 'geometry-area-perimeter', 2, 'mc', 'practice', '{"en": "A square has an area of 49 m². How long is one side?", "ko": "넓이가 49m²인 정사각형의 한 변의 길이는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "6 m"}}, {"id": "b", "text_i18n": {"en": "7 m"}}, {"id": "c", "text_i18n": {"en": "12.25 m"}}, {"id": "d", "text_i18n": {"en": "24.5 m"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Side = √49 = 7 m.", "ko": "한 변 = √49 = 7m입니다."}'::jsonb, 'published'),
('math', 'geometry-area-perimeter', 3, 'mc', 'practice', '{"en": "An 8 m × 5 m rectangle has a 4 m × 2 m rectangular piece cut out. What is the remaining area?", "ko": "8m × 5m 직사각형에서 4m × 2m 조각을 잘라냈습니다. 남은 넓이는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "48 m²"}}, {"id": "b", "text_i18n": {"en": "40 m²"}}, {"id": "c", "text_i18n": {"en": "32 m²"}}, {"id": "d", "text_i18n": {"en": "26 m²"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "40 − 8 = 32 m².", "ko": "전체 40m² − 잘라낸 8m² = 32m²입니다."}'::jsonb, 'published'),
('math', 'geometry-volume', 1, 'mc', 'practice', '{"en": "What is the volume of a box 5 cm × 4 cm × 3 cm?", "ko": "5cm × 4cm × 3cm 상자의 부피는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "12 cm³"}}, {"id": "b", "text_i18n": {"en": "60 cm³"}}, {"id": "c", "text_i18n": {"en": "94 cm³"}}, {"id": "d", "text_i18n": {"en": "120 cm³"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Volume = 5 × 4 × 3 = 60 cm³.", "ko": "부피 = 5 × 4 × 3 = 60cm³입니다."}'::jsonb, 'published'),
('math', 'geometry-volume', 3, 'mc', 'practice', '{"en": "A cylinder has radius 3 cm and height 10 cm. What is its volume? (π ≈ 3.14)", "ko": "반지름 3cm, 높이 10cm인 원기둥의 부피는? (π ≈ 3.14)"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "94.2 cm³"}}, {"id": "b", "text_i18n": {"en": "188.4 cm³"}}, {"id": "c", "text_i18n": {"en": "282.6 cm³"}}, {"id": "d", "text_i18n": {"en": "942 cm³"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "V = πr²h = 3.14 × 9 × 10 = 282.6 cm³.", "ko": "V = πr²h = 3.14 × 9 × 10 = 282.6cm³입니다."}'::jsonb, 'published'),
('math', 'geometry-volume', 2, 'mc', 'practice', '{"en": "A cube has a volume of 27 cm³. How long is one edge?", "ko": "부피가 27cm³인 정육면체의 한 모서리 길이는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "3 cm"}}, {"id": "b", "text_i18n": {"en": "9 cm"}}, {"id": "c", "text_i18n": {"en": "5.2 cm"}}, {"id": "d", "text_i18n": {"en": "13.5 cm"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "3 × 3 × 3 = 27, so each edge is 3 cm.", "ko": "3 × 3 × 3 = 27이므로 한 모서리는 3cm입니다."}'::jsonb, 'published'),
('math', 'geometry-circles', 2, 'mc', 'practice', '{"en": "What is the circumference of a circle with radius 5 cm? (π ≈ 3.14)", "ko": "반지름 5cm인 원의 둘레는? (π ≈ 3.14)"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "15.7 cm"}}, {"id": "b", "text_i18n": {"en": "31.4 cm"}}, {"id": "c", "text_i18n": {"en": "78.5 cm"}}, {"id": "d", "text_i18n": {"en": "25 cm"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "C = 2πr = 2 × 3.14 × 5 = 31.4 cm.", "ko": "둘레 = 2πr = 2 × 3.14 × 5 = 31.4cm입니다."}'::jsonb, 'published'),
('math', 'geometry-circles', 2, 'mc', 'practice', '{"en": "What is the area of a circle with radius 4 cm? (π ≈ 3.14)", "ko": "반지름 4cm인 원의 넓이는? (π ≈ 3.14)"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "12.56 cm²"}}, {"id": "b", "text_i18n": {"en": "25.12 cm²"}}, {"id": "c", "text_i18n": {"en": "50.24 cm²"}}, {"id": "d", "text_i18n": {"en": "100.48 cm²"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "A = πr² = 3.14 × 16 = 50.24 cm².", "ko": "넓이 = πr² = 3.14 × 16 = 50.24cm²입니다."}'::jsonb, 'published'),
('math', 'geometry-circles', 1, 'mc', 'practice', '{"en": "A circle has a diameter of 14 cm. What is its radius?", "ko": "지름이 14cm인 원의 반지름은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "7 cm"}}, {"id": "b", "text_i18n": {"en": "14 cm"}}, {"id": "c", "text_i18n": {"en": "28 cm"}}, {"id": "d", "text_i18n": {"en": "3.5 cm"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Radius = diameter ÷ 2 = 14 ÷ 2 = 7 cm.", "ko": "반지름 = 지름 ÷ 2 = 7cm입니다."}'::jsonb, 'published'),
('math', 'geometry-angles', 1, 'mc', 'practice', '{"en": "Two angles are complementary. One is 35°. What is the other?", "ko": "두 각이 서로 여각(합 90°)입니다. 한 각이 35°라면 다른 각은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "45°"}}, {"id": "b", "text_i18n": {"en": "55°"}}, {"id": "c", "text_i18n": {"en": "65°"}}, {"id": "d", "text_i18n": {"en": "145°"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Complementary angles sum to 90°: 90 − 35 = 55°.", "ko": "여각의 합은 90°이므로 90 − 35 = 55°입니다."}'::jsonb, 'published'),
('math', 'geometry-angles', 2, 'mc', 'practice', '{"en": "A triangle has angles of 65° and 45°. What is the third angle?", "ko": "삼각형의 두 각이 65°와 45°입니다. 나머지 한 각은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "60°"}}, {"id": "b", "text_i18n": {"en": "70°"}}, {"id": "c", "text_i18n": {"en": "80°"}}, {"id": "d", "text_i18n": {"en": "110°"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Angles in a triangle sum to 180°: 180 − 65 − 45 = 70°.", "ko": "삼각형 내각의 합은 180°이므로 180 − 65 − 45 = 70°입니다."}'::jsonb, 'published'),
('math', 'geometry-angles', 2, 'mc', 'practice', '{"en": "Two lines cross. One angle measures 120°. What is the angle directly opposite (vertical) to it?", "ko": "두 직선이 만나 한 각이 120°입니다. 맞꼭지각의 크기는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "30°"}}, {"id": "b", "text_i18n": {"en": "60°"}}, {"id": "c", "text_i18n": {"en": "120°"}}, {"id": "d", "text_i18n": {"en": "240°"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Vertical angles are always equal, so it is also 120°.", "ko": "맞꼭지각은 항상 서로 같으므로 120°입니다."}'::jsonb, 'published'),
('math', 'pythagorean-theorem', 2, 'mc', 'practice', '{"en": "A right triangle has legs of 6 and 8. What is the hypotenuse?", "ko": "직각삼각형의 두 변이 6과 8입니다. 빗변의 길이는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "10"}}, {"id": "b", "text_i18n": {"en": "12"}}, {"id": "c", "text_i18n": {"en": "14"}}, {"id": "d", "text_i18n": {"en": "48"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "c² = 6² + 8² = 36 + 64 = 100, so c = 10.", "ko": "c² = 6² + 8² = 100이므로 c = 10입니다."}'::jsonb, 'published'),
('math', 'pythagorean-theorem', 3, 'mc', 'practice', '{"en": "A right triangle has a hypotenuse of 13 and one leg of 5. What is the other leg?", "ko": "직각삼각형의 빗변이 13, 한 변이 5입니다. 나머지 변은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "8"}}, {"id": "b", "text_i18n": {"en": "12"}}, {"id": "c", "text_i18n": {"en": "14"}}, {"id": "d", "text_i18n": {"en": "18"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "b² = 13² − 5² = 169 − 25 = 144, so b = 12.", "ko": "b² = 13² − 5² = 144이므로 b = 12입니다."}'::jsonb, 'published'),
('math', 'coordinate-plane', 2, 'mc', 'practice', '{"en": "What is the distance between the points (2, 3) and (2, 9)?", "ko": "점 (2, 3)과 (2, 9) 사이의 거리는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "4"}}, {"id": "b", "text_i18n": {"en": "6"}}, {"id": "c", "text_i18n": {"en": "7"}}, {"id": "d", "text_i18n": {"en": "12"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Same x-coordinate, so distance = 9 − 3 = 6.", "ko": "x좌표가 같으므로 거리는 y좌표 차이인 9 − 3 = 6입니다."}'::jsonb, 'published'),
('math', 'coordinate-plane', 1, 'mc', 'practice', '{"en": "In which quadrant is the point (−3, 5)?", "ko": "점 (−3, 5)는 몇 사분면에 있나요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Quadrant I"}}, {"id": "b", "text_i18n": {"en": "Quadrant II"}}, {"id": "c", "text_i18n": {"en": "Quadrant III"}}, {"id": "d", "text_i18n": {"en": "Quadrant IV"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "x is negative and y is positive → Quadrant II (upper left).", "ko": "x가 음수이고 y가 양수이면 제2사분면(왼쪽 위)입니다."}'::jsonb, 'published'),
('math', 'data-statistics', 1, 'mc', 'practice', '{"en": "What is the median of 3, 7, 8, 12, 15?", "ko": "3, 7, 8, 12, 15의 중앙값은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "7"}}, {"id": "b", "text_i18n": {"en": "8"}}, {"id": "c", "text_i18n": {"en": "9"}}, {"id": "d", "text_i18n": {"en": "12"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "The values are already ordered; the middle (3rd of 5) value is 8.", "ko": "이미 크기순이며 5개 중 가운데(3번째) 값은 8입니다."}'::jsonb, 'published'),
('math', 'data-statistics', 1, 'mc', 'practice', '{"en": "What is the mode of 4, 4, 6, 7, 7, 7?", "ko": "4, 4, 6, 7, 7, 7의 최빈값은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "4"}}, {"id": "b", "text_i18n": {"en": "6"}}, {"id": "c", "text_i18n": {"en": "7"}}, {"id": "d", "text_i18n": {"en": "5.8"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "7 appears three times — more than any other value.", "ko": "7이 세 번으로 가장 많이 나타납니다."}'::jsonb, 'published'),
('math', 'data-statistics', 1, 'mc', 'practice', '{"en": "What is the range of 12, 5, 9, 20?", "ko": "12, 5, 9, 20의 범위(range)는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "8"}}, {"id": "b", "text_i18n": {"en": "11.5"}}, {"id": "c", "text_i18n": {"en": "15"}}, {"id": "d", "text_i18n": {"en": "20"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Range = max − min = 20 − 5 = 15.", "ko": "범위 = 최댓값 − 최솟값 = 20 − 5 = 15입니다."}'::jsonb, 'published'),
('math', 'data-statistics', 2, 'mc', 'practice', '{"en": "What is the mean of 6, 9, 12, 13?", "ko": "6, 9, 12, 13의 평균은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "9"}}, {"id": "b", "text_i18n": {"en": "10"}}, {"id": "c", "text_i18n": {"en": "10.5"}}, {"id": "d", "text_i18n": {"en": "40"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "(6+9+12+13) ÷ 4 = 40 ÷ 4 = 10.", "ko": "(6+9+12+13) ÷ 4 = 40 ÷ 4 = 10입니다."}'::jsonb, 'published'),
('math', 'data-statistics', 2, 'mc', 'practice', '{"en": "A bag has 3 red, 4 blue, and 5 green marbles. What is the probability of drawing a red marble?", "ko": "주머니에 빨강 3개, 파랑 4개, 초록 5개 구슬이 있습니다. 빨강을 뽑을 확률은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "1/3"}}, {"id": "b", "text_i18n": {"en": "1/4"}}, {"id": "c", "text_i18n": {"en": "3/9"}}, {"id": "d", "text_i18n": {"en": "1/12"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "3 red out of 12 total = 3/12 = 1/4.", "ko": "전체 12개 중 빨강 3개이므로 3/12 = 1/4입니다."}'::jsonb, 'published'),
('rla', 'grammar-verbs', 1, 'mc', 'practice', '{"en": "Choose the correct past tense: \"Yesterday, she ___ to the market.\"", "ko": "올바른 과거형을 고르세요: \"Yesterday, she ___ to the market.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "go"}}, {"id": "b", "text_i18n": {"en": "goes"}}, {"id": "c", "text_i18n": {"en": "went"}}, {"id": "d", "text_i18n": {"en": "gone"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "\"Go\" has an irregular past tense: \"went\". \"Gone\" needs a helping verb (has gone).", "ko": "\"go\"의 과거형은 불규칙형 \"went\"입니다. \"gone\"은 조동사와 함께 써야 합니다(has gone)."}'::jsonb, 'published'),
('rla', 'grammar-verbs', 2, 'mc', 'practice', '{"en": "Choose the correct verb: \"The list of names ___ on the desk.\"", "ko": "올바른 동사를 고르세요: \"The list of names ___ on the desk.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "are"}}, {"id": "b", "text_i18n": {"en": "is"}}, {"id": "c", "text_i18n": {"en": "were"}}, {"id": "d", "text_i18n": {"en": "have been"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "The subject is \"the list\" (singular), not \"names\". Singular subject takes \"is\".", "ko": "주어는 복수 \"names\"가 아니라 단수 \"the list\"이므로 \"is\"를 씁니다."}'::jsonb, 'published'),
('rla', 'grammar-verbs', 2, 'mc', 'practice', '{"en": "Choose the correct form: \"Right now, the children ___ in the yard.\"", "ko": "올바른 형태를 고르세요: \"Right now, the children ___ in the yard.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "plays"}}, {"id": "b", "text_i18n": {"en": "played"}}, {"id": "c", "text_i18n": {"en": "are playing"}}, {"id": "d", "text_i18n": {"en": "was playing"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "\"Right now\" signals present progressive: are + -ing.", "ko": "\"Right now\"는 현재진행형 신호입니다: are + -ing."}'::jsonb, 'published'),
('rla', 'grammar-verbs', 3, 'mc', 'practice', '{"en": "Choose the correct form: \"By the time we arrived, the movie ___.\"", "ko": "올바른 형태를 고르세요: \"By the time we arrived, the movie ___.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "starts"}}, {"id": "b", "text_i18n": {"en": "had started"}}, {"id": "c", "text_i18n": {"en": "has started"}}, {"id": "d", "text_i18n": {"en": "will start"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "An action completed before another past action uses past perfect: had started.", "ko": "과거의 한 시점보다 먼저 끝난 일은 과거완료(had + p.p.)로 씁니다."}'::jsonb, 'published'),
('rla', 'grammar-pronouns', 2, 'mc', 'practice', '{"en": "Choose the correct pronoun: \"This secret stays between you and ___.\"", "ko": "올바른 대명사를 고르세요: \"This secret stays between you and ___.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "I"}}, {"id": "b", "text_i18n": {"en": "me"}}, {"id": "c", "text_i18n": {"en": "myself"}}, {"id": "d", "text_i18n": {"en": "mine"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "After a preposition like \"between\", use the object pronoun \"me\".", "ko": "전치사(between) 뒤에는 목적격 대명사 \"me\"를 씁니다."}'::jsonb, 'published'),
('rla', 'grammar-pronouns', 2, 'mc', 'practice', '{"en": "Choose the correct word: \"The team celebrated ___ victory.\"", "ko": "올바른 단어를 고르세요: \"The team celebrated ___ victory.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "it''s"}}, {"id": "b", "text_i18n": {"en": "its"}}, {"id": "c", "text_i18n": {"en": "its''"}}, {"id": "d", "text_i18n": {"en": "their''s"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "\"Its\" (no apostrophe) is possessive. \"It''s\" means \"it is\".", "ko": "소유격은 아포스트로피 없는 \"its\"입니다. \"it''s\"는 \"it is\"의 축약형입니다."}'::jsonb, 'published'),
('rla', 'grammar-pronouns', 3, 'mc', 'practice', '{"en": "Choose the correct pronoun: \"___ should I say is calling?\"", "ko": "올바른 대명사를 고르세요: \"___ should I say is calling?\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Whom"}}, {"id": "b", "text_i18n": {"en": "Who"}}, {"id": "c", "text_i18n": {"en": "Whose"}}, {"id": "d", "text_i18n": {"en": "Which"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "The pronoun is the subject of \"is calling\", so use \"who\".", "ko": "이 대명사는 \"is calling\"의 주어이므로 주격 \"who\"를 씁니다."}'::jsonb, 'published'),
('rla', 'grammar-modifiers', 2, 'mc', 'practice', '{"en": "Choose the correct comparison: \"This road is ___ than that one.\"", "ko": "올바른 비교 표현을 고르세요: \"This road is ___ than that one.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "more long"}}, {"id": "b", "text_i18n": {"en": "longer"}}, {"id": "c", "text_i18n": {"en": "longest"}}, {"id": "d", "text_i18n": {"en": "most long"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Short adjectives form the comparative with -er: longer.", "ko": "짧은 형용사의 비교급은 -er을 붙입니다: longer."}'::jsonb, 'published'),
('rla', 'grammar-modifiers', 2, 'mc', 'practice', '{"en": "Which sentence is correct?", "ko": "올바른 문장을 고르세요."}'::jsonb, '[{"id": "a", "text_i18n": {"en": "He is the most tallest in the class."}}, {"id": "b", "text_i18n": {"en": "He is the tallest in the class."}}, {"id": "c", "text_i18n": {"en": "He is the taller in the class."}}, {"id": "d", "text_i18n": {"en": "He is most tall in the class."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Use either -est or \"most\", never both: tallest.", "ko": "최상급은 -est 또는 most 중 하나만 씁니다: tallest."}'::jsonb, 'published'),
('rla', 'grammar-modifiers', 3, 'mc', 'practice', '{"en": "Choose the correct word: \"She did ___ on the test.\"", "ko": "올바른 단어를 고르세요: \"She did ___ on the test.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "good"}}, {"id": "b", "text_i18n": {"en": "well"}}, {"id": "c", "text_i18n": {"en": "goodly"}}, {"id": "d", "text_i18n": {"en": "best"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "\"Well\" is the adverb that modifies the verb \"did\". \"Good\" is an adjective.", "ko": "동사 \"did\"를 꾸미는 부사는 \"well\"입니다. \"good\"은 형용사입니다."}'::jsonb, 'published'),
('rla', 'grammar-prepositions-conjunctions', 1, 'mc', 'practice', '{"en": "Choose the correct preposition: \"She is interested ___ science.\"", "ko": "올바른 전치사를 고르세요: \"She is interested ___ science.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "on"}}, {"id": "b", "text_i18n": {"en": "at"}}, {"id": "c", "text_i18n": {"en": "in"}}, {"id": "d", "text_i18n": {"en": "for"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "The fixed expression is \"interested in\".", "ko": "\"interested in\"이 굳어진 표현입니다."}'::jsonb, 'published'),
('rla', 'grammar-prepositions-conjunctions', 2, 'mc', 'practice', '{"en": "Complete the pair: \"Neither the manager ___ the workers knew about the change.\"", "ko": "짝을 완성하세요: \"Neither the manager ___ the workers knew about the change.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "or"}}, {"id": "b", "text_i18n": {"en": "nor"}}, {"id": "c", "text_i18n": {"en": "and"}}, {"id": "d", "text_i18n": {"en": "but"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "\"Neither\" always pairs with \"nor\".", "ko": "\"neither\"는 항상 \"nor\"와 짝을 이룹니다."}'::jsonb, 'published'),
('rla', 'grammar-prepositions-conjunctions', 3, 'mc', 'practice', '{"en": "Which word best combines the ideas? \"___ it was raining, the game continued.\"", "ko": "두 내용을 잇는 가장 알맞은 말은? \"___ it was raining, the game continued.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Because"}}, {"id": "b", "text_i18n": {"en": "Although"}}, {"id": "c", "text_i18n": {"en": "Unless"}}, {"id": "d", "text_i18n": {"en": "Therefore"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "The two ideas contrast (rain vs. continuing), so use \"Although\".", "ko": "비가 오는데도 경기가 계속됐다는 대조 관계이므로 \"Although\"가 맞습니다."}'::jsonb, 'published'),
('rla', 'punctuation-comma-apostrophe', 1, 'mc', 'practice', '{"en": "Which sentence uses commas correctly?", "ko": "쉼표를 올바르게 쓴 문장은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "We bought apples bananas, and grapes."}}, {"id": "b", "text_i18n": {"en": "We bought, apples, bananas and grapes."}}, {"id": "c", "text_i18n": {"en": "We bought apples, bananas, and grapes."}}, {"id": "d", "text_i18n": {"en": "We bought apples, bananas and, grapes."}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Separate every item in a list with commas: apples, bananas, and grapes.", "ko": "나열되는 항목 사이마다 쉼표를 씁니다: apples, bananas, and grapes."}'::jsonb, 'published'),
('rla', 'punctuation-comma-apostrophe', 2, 'mc', 'practice', '{"en": "Which sentence is punctuated correctly?", "ko": "구두점이 올바른 문장은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "After the storm we cleaned the yard."}}, {"id": "b", "text_i18n": {"en": "After the storm, we cleaned the yard."}}, {"id": "c", "text_i18n": {"en": "After, the storm we cleaned the yard."}}, {"id": "d", "text_i18n": {"en": "After the storm we cleaned, the yard."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Put a comma after an introductory phrase: \"After the storm,\".", "ko": "문장 앞에 오는 도입구 뒤에는 쉼표를 씁니다: \"After the storm,\"."}'::jsonb, 'published'),
('rla', 'punctuation-comma-apostrophe', 2, 'mc', 'practice', '{"en": "Choose the correct possessive: \"The ___ leashes are hanging by the door.\" (two dogs)", "ko": "올바른 소유격을 고르세요: \"The ___ leashes are hanging by the door.\" (개 두 마리)"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "dog''s"}}, {"id": "b", "text_i18n": {"en": "dogs"}}, {"id": "c", "text_i18n": {"en": "dogs''"}}, {"id": "d", "text_i18n": {"en": "dogs''s"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Plural noun ending in s takes only an apostrophe: dogs''.", "ko": "s로 끝나는 복수명사의 소유격은 아포스트로피만 붙입니다: dogs''."}'::jsonb, 'published'),
('rla', 'punctuation-comma-apostrophe', 1, 'mc', 'practice', '{"en": "Choose the correct word: \"___ going to love this book.\"", "ko": "올바른 단어를 고르세요: \"___ going to love this book.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Your"}}, {"id": "b", "text_i18n": {"en": "You''re"}}, {"id": "c", "text_i18n": {"en": "Yours"}}, {"id": "d", "text_i18n": {"en": "You"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "\"You''re\" = \"you are\". \"Your\" shows possession.", "ko": "\"You''re\"는 \"you are\"의 축약형입니다. \"your\"는 소유격입니다."}'::jsonb, 'published'),
('rla', 'punctuation-colon-semicolon', 3, 'mc', 'practice', '{"en": "Which sentence uses a semicolon correctly?", "ko": "세미콜론을 올바르게 쓴 문장은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "I finished the test; and left the room."}}, {"id": "b", "text_i18n": {"en": "The rain stopped; the sun came out."}}, {"id": "c", "text_i18n": {"en": "Because it was late; we went home."}}, {"id": "d", "text_i18n": {"en": "She bought; apples and pears."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "A semicolon joins two complete sentences that are closely related.", "ko": "세미콜론은 서로 관련된 두 개의 완전한 문장을 연결합니다."}'::jsonb, 'published'),
('rla', 'punctuation-colon-semicolon', 3, 'mc', 'practice', '{"en": "Which sentence uses a colon correctly?", "ko": "콜론을 올바르게 쓴 문장은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "You will need: paper, a pen, and a ruler."}}, {"id": "b", "text_i18n": {"en": "Bring the following: paper, a pen, and a ruler."}}, {"id": "c", "text_i18n": {"en": "Bring: the following paper, a pen, and a ruler."}}, {"id": "d", "text_i18n": {"en": "You will: need paper, a pen, and a ruler."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "A colon follows a complete sentence to introduce a list.", "ko": "콜론은 완전한 문장 뒤에서 목록을 소개할 때 씁니다."}'::jsonb, 'published'),
('rla', 'syntax-sentences', 2, 'mc', 'practice', '{"en": "Which of the following is a sentence fragment?", "ko": "다음 중 조각문(완전하지 않은 문장)은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "The bell rang."}}, {"id": "b", "text_i18n": {"en": "Running down the empty hallway."}}, {"id": "c", "text_i18n": {"en": "She opened the window."}}, {"id": "d", "text_i18n": {"en": "It rained all night."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "\"Running down the empty hallway\" has no subject or main verb.", "ko": "\"Running down the empty hallway\"에는 주어와 본동사가 없습니다."}'::jsonb, 'published'),
('rla', 'syntax-sentences', 3, 'mc', 'practice', '{"en": "Which is the best way to fix this run-on? \"The bus was late we missed the meeting.\"", "ko": "다음 이어진 문장(run-on)을 고치는 가장 좋은 방법은? \"The bus was late we missed the meeting.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "The bus was late, we missed the meeting."}}, {"id": "b", "text_i18n": {"en": "The bus was late, so we missed the meeting."}}, {"id": "c", "text_i18n": {"en": "The bus was late we, missed the meeting."}}, {"id": "d", "text_i18n": {"en": "The bus, was late we missed the meeting."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Join two sentences with a comma + conjunction (so). A comma alone creates a comma splice.", "ko": "두 문장은 쉼표 + 접속사(so)로 연결합니다. 쉼표만 쓰면 쉼표 오용(comma splice)입니다."}'::jsonb, 'published'),
('rla', 'syntax-sentences', 2, 'mc', 'practice', '{"en": "Which sentence is a compound sentence?", "ko": "다음 중 중문(두 개의 독립절)은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "The tired old man slept."}}, {"id": "b", "text_i18n": {"en": "When the sun set, we left."}}, {"id": "c", "text_i18n": {"en": "I cooked dinner, and she washed the dishes."}}, {"id": "d", "text_i18n": {"en": "Running quickly through the park."}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Two independent clauses joined by \", and\" make a compound sentence.", "ko": "두 개의 독립절이 \", and\"로 연결되면 중문입니다."}'::jsonb, 'published'),
('rla', 'syntax-sentences', 3, 'mc', 'practice', '{"en": "In \"Although he was tired, he finished the report,\" the clause \"Although he was tired\" is…", "ko": "\"Although he was tired, he finished the report\"에서 \"Although he was tired\"는 무엇인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "An independent clause"}}, {"id": "b", "text_i18n": {"en": "A dependent clause"}}, {"id": "c", "text_i18n": {"en": "A complete sentence"}}, {"id": "d", "text_i18n": {"en": "A prepositional phrase"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "It starts with the subordinating word \"although\" and cannot stand alone.", "ko": "종속접속사 \"although\"로 시작하며 홀로 문장이 될 수 없는 종속절입니다."}'::jsonb, 'published'),
('rla', 'conventions', 1, 'mc', 'practice', '{"en": "Which sentence is capitalized correctly?", "ko": "대문자를 올바르게 쓴 문장은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "my cousin lives in chiang mai, thailand."}}, {"id": "b", "text_i18n": {"en": "My cousin lives in Chiang Mai, Thailand."}}, {"id": "c", "text_i18n": {"en": "My Cousin lives in chiang mai, Thailand."}}, {"id": "d", "text_i18n": {"en": "my Cousin lives in Chiang mai, thailand."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Capitalize the first word and proper nouns (Chiang Mai, Thailand).", "ko": "문장 첫 단어와 고유명사(Chiang Mai, Thailand)는 대문자로 씁니다."}'::jsonb, 'published'),
('rla', 'conventions', 2, 'mc', 'practice', '{"en": "Choose the correct word: \"They left ___ shoes by the door.\"", "ko": "올바른 단어를 고르세요: \"They left ___ shoes by the door.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "there"}}, {"id": "b", "text_i18n": {"en": "they''re"}}, {"id": "c", "text_i18n": {"en": "their"}}, {"id": "d", "text_i18n": {"en": "theirs"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "\"Their\" shows possession. \"There\" is a place; \"they''re\" = \"they are\".", "ko": "소유격은 \"their\"입니다. \"there\"는 장소, \"they''re\"는 \"they are\"입니다."}'::jsonb, 'published'),
('rla', 'conventions', 3, 'mc', 'practice', '{"en": "Choose the correct word: \"The new schedule will ___ everyone in the office.\"", "ko": "올바른 단어를 고르세요: \"The new schedule will ___ everyone in the office.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "affect"}}, {"id": "b", "text_i18n": {"en": "effect"}}, {"id": "c", "text_i18n": {"en": "affects"}}, {"id": "d", "text_i18n": {"en": "effected"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "\"Affect\" is the verb (to influence); \"effect\" is usually a noun.", "ko": "동사(영향을 주다)는 \"affect\", \"effect\"는 주로 명사(결과)입니다."}'::jsonb, 'published'),
('rla', 'usage-style', 3, 'mc', 'practice', '{"en": "Which revision removes the redundancy? \"He returned back to his hometown.\"", "ko": "중복 표현을 없앤 수정은? \"He returned back to his hometown.\""}'::jsonb, '[{"id": "a", "text_i18n": {"en": "He returned back again to his hometown."}}, {"id": "b", "text_i18n": {"en": "He returned to his hometown."}}, {"id": "c", "text_i18n": {"en": "He went returned to his hometown."}}, {"id": "d", "text_i18n": {"en": "He returned backwards to his hometown."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "\"Return\" already means \"go back\", so \"back\" is redundant.", "ko": "\"return\"에 이미 \"돌아가다\"라는 뜻이 있어 \"back\"은 중복입니다."}'::jsonb, 'published'),
('rla', 'usage-style', 3, 'mc', 'practice', '{"en": "Which sentence is most appropriate for a formal job application letter?", "ko": "격식 있는 입사 지원서에 가장 알맞은 문장은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Hey, I really wanna work for you guys."}}, {"id": "b", "text_i18n": {"en": "I would welcome the opportunity to join your team."}}, {"id": "c", "text_i18n": {"en": "So yeah, hire me maybe?"}}, {"id": "d", "text_i18n": {"en": "Gimme a chance, you won''t regret it!"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Formal writing avoids slang and casual phrases.", "ko": "격식체에서는 속어와 구어체 표현을 피합니다."}'::jsonb, 'published'),
('rla', 'reading-main-idea', 2, 'mc', 'practice', '{"en": "\"Recycling one aluminum can saves enough energy to run a TV for three hours. Yet most cans still end up in landfills. Better recycling habits could save huge amounts of energy every year.\" — What is the main idea?", "ko": "\"Recycling one aluminum can...\" 지문의 중심 생각은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "TVs use too much energy."}}, {"id": "b", "text_i18n": {"en": "Recycling cans could save significant energy."}}, {"id": "c", "text_i18n": {"en": "Landfills are getting bigger."}}, {"id": "d", "text_i18n": {"en": "Aluminum is expensive to produce."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Every sentence supports the point that recycling cans saves energy.", "ko": "모든 문장이 ''캔 재활용이 에너지를 절약한다''는 핵심을 뒷받침합니다."}'::jsonb, 'published'),
('rla', 'reading-main-idea', 3, 'mc', 'practice', '{"en": "\"Small daily habits shape long-term success. Reading ten minutes a day adds up to dozens of books over a decade. Saving a little each week grows into real savings. Big goals are usually reached through small, repeated actions.\" — Which title fits best?", "ko": "\"Small daily habits...\" 지문에 가장 어울리는 제목은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "The Power of Small Habits"}}, {"id": "b", "text_i18n": {"en": "How to Read Faster"}}, {"id": "c", "text_i18n": {"en": "Why Saving Money Is Hard"}}, {"id": "d", "text_i18n": {"en": "Setting Big Goals"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Reading and saving are examples; the passage is about small habits leading to big results.", "ko": "독서와 저축은 예시일 뿐이고, 글 전체는 작은 습관이 큰 결과를 만든다는 내용입니다."}'::jsonb, 'published'),
('rla', 'reading-inference', 3, 'mc', 'practice', '{"en": "\"Dara checked the sky, packed an umbrella, and moved the picnic food back into the fridge.\" — What can you infer?", "ko": "\"Dara checked the sky...\" 에서 추론할 수 있는 것은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Dara expects rain."}}, {"id": "b", "text_i18n": {"en": "Dara dislikes picnics."}}, {"id": "c", "text_i18n": {"en": "The fridge is broken."}}, {"id": "d", "text_i18n": {"en": "It is winter."}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Checking the sky, packing an umbrella, and postponing the picnic all suggest expected rain.", "ko": "하늘을 살피고 우산을 챙기고 소풍 음식을 넣어둔 행동 모두 비를 예상한다는 단서입니다."}'::jsonb, 'published'),
('rla', 'reading-inference', 3, 'mc', 'practice', '{"en": "\"The waiting room was full, and the receptionist kept apologizing for the delay. Several patients sighed and glanced at the clock.\" — How do the patients most likely feel?", "ko": "\"The waiting room was full...\" 에서 환자들의 기분은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Excited"}}, {"id": "b", "text_i18n": {"en": "Frustrated"}}, {"id": "c", "text_i18n": {"en": "Relaxed"}}, {"id": "d", "text_i18n": {"en": "Proud"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Sighing and glancing at the clock are signs of frustration with waiting.", "ko": "한숨을 쉬고 시계를 자꾸 보는 행동은 기다림에 대한 답답함(frustration)의 표시입니다."}'::jsonb, 'published'),
('rla', 'reading-detail', 2, 'mc', 'practice', '{"en": "\"The library is open 9–6 on weekdays and 10–2 on Saturdays. It is closed on Sundays and public holidays.\" — When does the library open on Saturday?", "ko": "\"The library is open...\" — 토요일 개관 시간은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "9 a.m."}}, {"id": "b", "text_i18n": {"en": "10 a.m."}}, {"id": "c", "text_i18n": {"en": "2 p.m."}}, {"id": "d", "text_i18n": {"en": "It is closed."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "The passage says Saturdays are 10–2, so it opens at 10 a.m.", "ko": "토요일은 10–2시로 명시되어 있으므로 오전 10시에 엽니다."}'::jsonb, 'published'),
('rla', 'reading-authors-purpose', 3, 'mc', 'practice', '{"en": "\"Don''t wait until it''s too late — schedule your free dental checkup today and keep your smile healthy for years to come!\" — What is the author''s main purpose?", "ko": "\"Don''t wait until it''s too late...\" 글쓴이의 주된 목적은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "To entertain readers with a story"}}, {"id": "b", "text_i18n": {"en": "To persuade readers to get a checkup"}}, {"id": "c", "text_i18n": {"en": "To explain how teeth grow"}}, {"id": "d", "text_i18n": {"en": "To compare types of toothpaste"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Commands like \"schedule today\" and emotional appeals are persuasive techniques.", "ko": "\"오늘 예약하세요\" 같은 권유와 감정에 호소하는 표현은 설득이 목적임을 보여줍니다."}'::jsonb, 'published'),
('rla', 'reading-vocab-context', 3, 'mc', 'practice', '{"en": "\"The instructions were so ambiguous that half the class did the assignment one way and half did it another.\" — What does \"ambiguous\" most nearly mean?", "ko": "\"The instructions were so ambiguous...\" 에서 \"ambiguous\"의 뜻에 가장 가까운 것은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Clear"}}, {"id": "b", "text_i18n": {"en": "Unclear"}}, {"id": "c", "text_i18n": {"en": "Short"}}, {"id": "d", "text_i18n": {"en": "Difficult"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "The class understood it two different ways, so the instructions were unclear.", "ko": "학생들이 두 가지로 다르게 이해했다는 것은 지시가 불명확했다는 뜻입니다."}'::jsonb, 'published');